    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    horizontal_2 = set()
    vertical = set()

    def paint(r, c, color):
        if 0 <= r < h and 0 <= c < w:
            out[r][c] = color

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 1:
                # Two steps right, then one step up; same-color endpoint.
                paint(r, c + 1, 5)
                paint(r, c + 2, 5)
                paint(r - 1, c + 2, 1)
            elif color == 2:
                # Four steps left, ending in a copy of the marker.
                for d in range(1, 5):
                    rr, cc = r, c - d
                    paint(rr, cc, 2 if d == 4 else 5)
                    if 0 <= rr < h and 0 <= cc < w:
                        horizontal_2.add((rr, cc))
            elif color == 3:
                # Three steps down, ending in a copy of the marker.
                for d in range(1, 4):
                    rr, cc = r + d, c
                    paint(rr, cc, 3 if d == 3 else 5)
                    if 0 <= rr < h and 0 <= cc < w:
                        vertical.add((rr, cc))
            elif color == 6:
                # Six steps up, ending in a copy of the marker.
                for d in range(1, 7):
                    rr, cc = r - d, c
                    paint(rr, cc, 6 if d == 6 else 5)
                    if 0 <= rr < h and 0 <= cc < w:
                        vertical.add((rr, cc))

    crossings = horizontal_2 & vertical
    for r, c in crossings:
        paint(r, c, 4)
